<script setup>
import {ref} from 'vue'; import {Head,useForm,router} from '@inertiajs/vue3'; import Layout from '@/Layouts/main.vue';
const props=defineProps({members:Object,coupons:Array,filters:Object,temporaryCredentials:Object}); const showModal=ref(false); const showInvitation=ref(!!props.temporaryCredentials); const search=ref(props.filters.search||'');
const form=useForm({name:'',dni:'',email:'',phone:'',coupon_ids:props.coupons.map(c=>c.id)});
const submit=()=>form.post(route('members.store'),{preserveScroll:true,onSuccess:()=>{showModal.value=false;showInvitation.value=true;form.reset();form.coupon_ids=props.coupons.map(c=>c.id)}});
const filter=()=>router.get(route('members.index'),{search:search.value},{preserveState:true,replace:true}); const toggle=m=>router.patch(route('members.status',m.id),{}, {preserveScroll:true});
function invitationCanvas(){const d=props.temporaryCredentials,c=document.createElement('canvas');c.width=1080;c.height=1350;const x=c.getContext('2d');x.fillStyle='#fff8e9';x.fillRect(0,0,c.width,c.height);x.fillStyle='#332820';x.fillRect(0,0,c.width,310);x.fillStyle='#bfb574';x.fillRect(72,270,936,8);x.textAlign='center';x.fillStyle='#fff8e9';x.font='700 42px Georgia';x.fillText('HACIENDA',540,105);x.font='700 82px Georgia';x.fillText('MONTE RICO',540,185);x.fillStyle='#bfb574';x.font='600 18px Arial';x.fillText('CLUB DE SOCIOS',540,235);x.fillStyle='#8f3b28';x.font='700 20px Arial';x.fillText('UNA INVITACIÓN ESPECIAL PARA',540,400);x.fillStyle='#332820';x.font='700 54px Georgia';wrap(x,d.name,540,485,850,64);x.fillStyle='#6f665e';x.font='28px Arial';x.fillText('Tu oasis de beneficios exclusivos te espera.',540,625);round(x,120,700,840,300,28);x.fillStyle='#f1ebdd';x.fill();x.textAlign='left';x.fillStyle='#8f3b28';x.font='700 18px Arial';x.fillText('USUARIO',180,780);x.fillStyle='#332820';x.font='700 38px Arial';x.fillText(d.user,180,830);x.fillStyle='#8f3b28';x.font='700 18px Arial';x.fillText('CONTRASEÑA TEMPORAL',180,900);x.fillStyle='#332820';x.font='700 38px Arial';x.fillText(d.password,180,950);x.textAlign='center';x.fillStyle='#576443';x.font='700 24px Arial';x.fillText('Al ingresar deberás crear una nueva contraseña.',540,1080);x.fillStyle='#80766d';x.font='22px Arial';x.fillText(d.login_url,540,1140);x.fillStyle='#8f3b28';x.fillRect(390,1210,300,4);x.font='18px Arial';x.fillText('HACIENDA MONTE RICO · LIMA, PERÚ',540,1260);return c}
function round(x,a,b,w,h,r){x.beginPath();x.roundRect(a,b,w,h,r)} function wrap(x,t,c,y,m,l){const w=t.split(' ');let s='';for(const q of w){const n=s+q+' ';if(x.measureText(n).width>m){x.fillText(s,c,y);s=q+' ';y+=l}else s=n}x.fillText(s,c,y)}
function downloadInvitation(){const a=document.createElement('a');a.download=`invitacion-${props.temporaryCredentials.user}.png`;a.href=invitationCanvas().toDataURL('image/png');a.click()}
async function shareInvitation(){const c=invitationCanvas();c.toBlob(async blob=>{const file=new File([blob],`invitacion-${props.temporaryCredentials.user}.png`,{type:'image/png'});if(navigator.canShare?.({files:[file]})){await navigator.share({title:'Invitación Hacienda MonteRico',text:`Invitación para ${props.temporaryCredentials.name}`,files:[file]})}else{downloadInvitation();window.open(`https://wa.me/${(props.temporaryCredentials.phone||'').replace(/\D/g,'')}?text=${encodeURIComponent('Te envío tu invitación al Club de Socios de Hacienda MonteRico. Adjunta la imagen descargada.')}`,'_blank')}})}
</script>
<template><Layout><Head title="Socios"/><div class="hmr-page"><header><div><span>DIRECTORIO</span><h1>Socios</h1><p>Registra miembros y administra el acceso a sus beneficios.</p></div><button @click="showModal=true"><i class="ri-user-add-line"></i> Nuevo socio</button></header><section class="toolbar"><div class="search"><i class="ri-search-line"></i><input v-model="search" @keyup.enter="filter" placeholder="Buscar por nombre, DNI, código o correo"></div><button class="filter" @click="filter">Buscar</button><small>{{members.total}} socios registrados</small></section><section class="panel"><div class="table-responsive"><table><thead><tr><th>Socio</th><th>Código / contacto</th><th>Invitación</th><th>Disponibles</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="m in members.data" :key="m.id"><td><b>{{m.name}}</b><small>{{m.dni||'Sin DNI'}}</small></td><td><b>{{m.member_code}}</b><small>{{m.phone||m.email||'Sin contacto'}}</small></td><td><span :class="['invite-status',m.invitation_used_at?'used':'pending']"><i :class="m.invitation_used_at?'ri-checkbox-circle-line':'ri-time-line'"></i>{{m.invitation_used_at?'Utilizada':'Pendiente'}}</span><small v-if="m.invitation_used_at">{{new Date(m.invitation_used_at).toLocaleString('es-PE')}}</small></td><td><div class="coupon-count"><i class="ri-coupon-3-line"></i>{{m.available_coupons_count}}</div></td><td><span :class="['badge',m.status]">{{m.status==='active'?'Activo':'Bloqueado'}}</span></td><td><button class="state" @click="toggle(m)">{{m.status==='active'?'Bloquear':'Activar'}}</button></td></tr></tbody></table></div></section>
<div v-if="showModal" class="modal-mask" @click.self="showModal=false"><form class="member-modal" @submit.prevent="submit"><div class="modal-head"><div><span>NUEVO REGISTRO</span><h2>Registrar socio</h2></div><button type="button" @click="showModal=false"><i class="ri-close-line"></i></button></div><p>Solo el nombre es obligatorio. El código y la contraseña se generan automáticamente.</p><div class="form-grid"><label class="wide">Nombre completo <em>*</em><input v-model="form.name" required><small>{{form.errors.name}}</small></label><label>DNI <i>Opcional</i><input v-model="form.dni" inputmode="numeric" maxlength="8"><small>{{form.errors.dni}}</small></label><label>Celular <i>Opcional</i><input v-model="form.phone" type="tel" placeholder="Ej. 999 999 999"><small>{{form.errors.phone}}</small></label><label class="wide">Correo electrónico <i>Opcional</i><input v-model="form.email" type="email"><small>{{form.errors.email}}</small></label><fieldset class="wide"><legend>Cupones iniciales <i>Opcional</i></legend><label v-for="c in coupons" :key="c.id" class="check"><input v-model="form.coupon_ids" type="checkbox" :value="c.id"> {{c.name}}</label></fieldset></div><div class="credential-note"><i class="ri-lock-password-line"></i><div><b>Primer ingreso protegido</b><span>La invitación figurará como utilizada cuando el socio inicie sesión y deberá cambiar su contraseña.</span></div></div><footer><button type="button" class="cancel" @click="showModal=false">Cancelar</button><button type="submit" class="save" :disabled="form.processing">Registrar socio</button></footer></form></div>
<div v-if="showInvitation&&temporaryCredentials" class="modal-mask"><section class="invitation-modal"><button class="close" @click="showInvitation=false"><i class="ri-close-line"></i></button><div class="invite-card"><div class="invite-brand">HACIENDA <strong>MONTE RICO</strong><small>CLUB DE SOCIOS</small></div><span>UNA INVITACIÓN ESPECIAL PARA</span><h2>{{temporaryCredentials.name}}</h2><p>Tu oasis de beneficios exclusivos te espera.</p><div class="access"><small>USUARIO</small><b>{{temporaryCredentials.user}}</b><small>CONTRASEÑA TEMPORAL</small><b>{{temporaryCredentials.password}}</b></div><footer>Al ingresar deberás crear una nueva contraseña.</footer></div><div class="invite-actions"><button @click="downloadInvitation"><i class="ri-download-2-line"></i> Descargar imagen</button><button class="whatsapp" @click="shareInvitation"><i class="ri-whatsapp-line"></i> Compartir</button></div><small>La contraseña se muestra una sola vez. Descarga la invitación antes de cerrar.</small></section></div>
</div></Layout></template>
<style scoped>.hmr-page{max-width:1440px;margin:auto;color:#332820}.hmr-page>header{display:flex;justify-content:space-between;align-items:end}.hmr-page>header span,.modal-head span{font-size:10px;letter-spacing:.18em;color:#8f3b28;font-weight:800}h1,h2{font-family:Georgia,serif;margin:4px 0}h1{font-size:34px}.hmr-page>header p{color:#786f67}.hmr-page>header button,.save{background:#8f3b28;color:white;border:0;border-radius:9px;padding:12px 18px;font-weight:700}.toolbar{display:flex;align-items:center;gap:12px;background:#fff;padding:14px;border-radius:14px 14px 0 0;margin-top:25px;border-bottom:1px solid #eee7da}.search{position:relative;flex:1}.search i{position:absolute;left:13px;top:10px}.search input{border:1px solid #e3dccf;border-radius:9px;padding:10px 12px 10px 38px;width:100%}.filter,.state{border:1px solid #8f3b28;background:transparent;color:#8f3b28;border-radius:8px;padding:8px 12px}.panel{background:#fff;border-radius:0 0 14px 14px;padding:0 18px}table{width:100%;border-collapse:collapse}th{font-size:10px;letter-spacing:.1em;color:#9c8a72;text-align:left;padding:13px 12px}td{padding:17px 12px;border-top:1px solid #f0eade}td small{display:block;color:#91877e}.coupon-count{color:#576443;font-weight:700}.badge,.invite-status{border-radius:20px;padding:6px 10px;font-size:11px}.active,.used{background:#e5eee3;color:#49603f}.blocked{background:#f4dfd9;color:#8f3b28}.pending{background:#f4eed5;color:#82743c}.invite-status i{margin-right:5px}.modal-mask{position:fixed;inset:0;background:rgba(25,25,25,.6);z-index:1060;display:grid;place-items:center;padding:20px}.member-modal,.invitation-modal{width:min(580px,100%);background:#fffaf1;border-radius:18px;padding:28px;position:relative}.modal-head{display:flex;justify-content:space-between}.modal-head button,.close{border:0;background:transparent;font-size:24px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.form-grid label{font-size:12px;font-weight:700}.form-grid label>i,legend i{font-style:normal;font-weight:400;color:#998e84;float:right}.form-grid em{color:#8f3b28}.form-grid input:not([type=checkbox]){display:block;width:100%;margin-top:7px;border:1px solid #ded5c7;border-radius:9px;padding:11px}.form-grid small{display:block;color:#8f3b28}.wide{grid-column:1/-1}fieldset{border:1px solid #ded5c7;border-radius:9px;padding:12px}legend{font-size:12px;font-weight:700}.check{display:block!important;margin:5px 0}.credential-note{display:flex;gap:12px;background:#edeedf;color:#576443;padding:14px;border-radius:10px;margin-top:18px}.credential-note span{display:block;font-size:12px}.member-modal footer{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}.cancel{border:1px solid #cfc5b7;background:transparent;border-radius:9px;padding:10px 17px}.invitation-modal{width:min(520px,100%);text-align:center}.close{position:absolute;right:12px;top:10px}.invite-card{background:#fff8e9;border:1px solid #d7cdbd}.invite-brand{background:#332820;color:#fff8e9;padding:25px;font:17px Georgia;display:flex;flex-direction:column}.invite-brand strong{font-size:33px}.invite-brand small{color:#bfb574;font:8px Arial;letter-spacing:.25em}.invite-card>span{display:block;color:#8f3b28;font-size:8px;letter-spacing:.18em;margin-top:25px}.invite-card h2{font-size:28px;margin:9px}.invite-card p{color:#756b62}.access{background:#eee7da;margin:20px 45px;padding:18px;text-align:left;border-radius:10px}.access small,.access b{display:block}.access small{font-size:8px;color:#8f3b28;margin-top:8px}.access b{font-size:20px}.invite-card footer{color:#576443;font-size:11px;padding:0 15px 24px}.invite-actions{display:flex;gap:10px;margin-top:18px}.invite-actions button{flex:1;border:1px solid #8f3b28;color:#8f3b28;background:white;border-radius:9px;padding:11px}.invite-actions .whatsapp{background:#247d4a;color:white;border-color:#247d4a}.invitation-modal>small{display:block;color:#8f3b28;margin-top:12px}@media(max-width:700px){.hmr-page>header{align-items:flex-start;gap:15px;flex-direction:column}.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}.invite-actions{flex-direction:column}}</style>
